input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it.todo("empty item list -- premium 5 G (processing fee only)");

  // --- Base premiums per main item type (parallel catalogue: one test per entry) ---
  it.todo("quote for a plain sword -- premium 105 G (100 base + 5 fee)");
  it.todo("quote for a plain amulet -- premium 65 G (60 base + 5 fee)");
  it.todo("quote for a plain staff -- premium 85 G (80 base + 5 fee)");
  it.todo("quote for a plain potion -- premium 45 G (40 base + 5 fee)");

  // --- Component base premiums (parallel catalogue: one test per entry) ---
  it.todo("quote for a single rune -- premium 30 G (25 base + 5 fee)");
  it.todo("quote for a single moonstone -- premium 30 G (25 base + 5 fee)");

  // --- Building block of 3 alike components ---
  it.todo("2 runes -- base premium 50 G (no block)");
  it.todo("3 runes -- base premium 60 G (block applies)");
  it.todo("4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -- base premium 175 G (no block at 7)");

  // --- 'Alike' means exactly the same type (resolves clarifying question) ---
  it.todo("2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers in isolation ---
  it.todo("cursed sword -- curse adds 50 % of the item base premium (100 -> 150)");
  it.todo("sword with enchantment 5 -- high-enchantment surcharge applies (100 -> 130)");
  it.todo("sword with enchantment 4 -- no high-enchantment surcharge (100 -> 100)");
  it.todo("cursed sword with enchantment 5 -- both surcharges apply (100 -> 180)");

  // --- Policy-wide modifiers in isolation ---
  it.todo("customer with exactly 2 years -- 20 % loyalty discount applies");
  it.todo("customer with 1 year -- no loyalty discount");
  it.todo("first insurance adds 10 % initial assessment surcharge to each quoted item");
  it.todo("second quote in a scenario -- 15 % follow-up contract discount applies");
  it.todo("third quote in a scenario -- 15 % follow-up contract discount applies");

  // --- Modifier scope on multi-item policies (resolves clarifying question) ---
  it.todo("cursed sword + plain amulet -- curse adds 50 G (50 % of the cursed sword only), not 80 G");

  // --- Rounding in the MHPCO's favor ---
  it.todo("premium yielding 197.5 G -- final premium 198 G (rounded up)");
  it.todo("payout yielding 350.5 G -- final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Insurance sum and cap ---
  it.todo("policy covering a sword and an amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes -- insurance sum 1750 G (block affects premium only), cap 3500 G");
  it.todo("cursed sword (premium 165 G) -- cap 2000 G, based on the unmodified insurance value");

  // --- Standard claim reimbursement ---
  it.todo("steel sword enchantment 3, damage 500 G -- payout 400 G (full minus 100 deductible)");
  it.todo("rune (no enchantment, no material), damage 200 G -- payout 100 G (full minus 100 deductible)");

  // --- Claim special clauses ---
  it.todo("steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % clause, then deductible)");
  it.todo("sword enchantment 8 exactly, dragon material, damage 1000 G -- payout 400 G (50 % clause wins)");
  it.todo("dragon sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon sword enchantment 9, damage 1000 G -- payout 400 G (50 % rule wins over dragon material)");

  // --- Deductible per damage event ---
  it.todo("one incident damaging a sword (500 G) and an amulet (300 G) -- payout 600 G (deductible once per damaged item)");
  it.todo("two swords insured, both damaged -- each damages entry gets its own deductible");

  // --- Cap exhaustion across successive claims ---
  it.todo("sword (cap 2000 G), first claim of 1500 G -- payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G -- payout 600 G, remainingCap 0 G (reduced to remaining cap)");

  // --- Error cases: domain layer rejects by throwing an Error ---
  // The spec defines only the CLI contract (non-zero exit + stderr); the adopted
  // reading is that the domain throws an Error and the CLI translates it.
  it.todo("quote with an unknown item type ('broomstick') -- throws an Error");
  it.todo("claim naming an item not covered by the policy (amulet when only a sword is insured) -- throws an Error");
  it.todo("claim naming a damage item with an unknown type -- throws an Error");
  it.todo("claim with more damage entries of a type than the policy covers -- throws an Error");
  it.todo("claim with a negative damage amount (-200) -- throws an Error");

  // --- CLI adapter behavior ---
  it.todo("CLI reads the schema example from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("CLI exits 0 on a valid scenario");
  it.todo("CLI exits non-zero, writes an error to stderr, and writes no results to stdout on an unknown item type");
  it.todo("CLI exits non-zero and writes an error to stderr on an invalid claim");
  it.todo("CLI processes steps sequentially so a claim can reference an earlier quote's policy by step index");
});
EOF
