import { describe, expect, it } from "vitest";
import { runScenario, type Item } from "./claim-office.js";

function premiumFor(items: Item[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({
    customer: { yearsWithMHPCO },
    steps: [{ op: "quote", items }],
  });

  return results[0].premium;
}

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("empty item list -- premium 5 G (processing fee only)", () => {
    expect(premiumFor([])).toBe(5);
  });

  // --- Base premiums per main item type (parallel catalogue: one test per entry) ---
  it("quote for a plain sword -- premium 105 G (100 base + 5 fee)", () => {
    expect(premiumFor([{ type: "sword" }])).toBe(105);
  });
  it("quote for a plain amulet -- premium 65 G (60 base + 5 fee)", () => {
    expect(premiumFor([{ type: "amulet" }])).toBe(65);
  });
  it.todo("quote for a plain staff -- premium 85 G (80 base + 5 fee)");
  it.todo("quote for a plain potion -- premium 45 G (40 base + 5 fee)");

  // --- Component base premiums (parallel catalogue: one test per entry) ---
  it.todo("quote for a single rune -- premium 30 G (25 base + 5 fee)");
  it.todo("quote for a single moonstone -- premium 30 G (25 base + 5 fee)");

  // --- Building block of 3 alike components ---
  it.todo("2 runes -- base premium 50 G (no block)");
  it.todo("3 runes -- base premium 60 G (block applies)");
  it.todo("4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -- base premium 175 G (no block at 7)");

  // --- 'Alike' means exactly the same type (resolves clarifying question) ---
  it.todo("2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
 Test Files  1 passed (1)
      Tests  3 passed | 49 todo (52)

