2	import { runScenario, type Item, type StepResult } from "./claim-office.js";
3	
4	function premiumOf(result: StepResult): number {
5	  if (!("premium" in result)) {
6	    throw new Error("expected a quote result");
7	  }
8	
9	  return result.premium;
10	}
11	
12	function premiumFor(items: Item[], yearsWithMHPCO = 0): number {
13	  const { results } = runScenario({
14	    customer: { yearsWithMHPCO },
15	    steps: [{ op: "quote", items }],
16	  });
17	
18	  return premiumOf(results[0]);
19	}
20	
21	function premiumsFor(itemsPerQuote: Item[][], yearsWithMHPCO = 0): number[] {
22	  const { results } = runScenario({
23	    customer: { yearsWithMHPCO },
24	    steps: itemsPerQuote.map((items) => ({ op: "quote" as const, items })),
25	  });
26	
27	  return results.map(premiumOf);
28	}
